import java.io.*;

public class Main {
    static int mod = 998244353;
    static int[] dp;

    static int idx(int i, int cpx, int cnx, int cpy, int cny, int bx, int by) {
        return ((((((i * 21 + cpx) * 21 + cnx) * 21 + cpy) * 21 + cny) * 2 + bx) * 2 + by);
    }

    static void add(int pos, int y) {
        dp[pos] += y;
        if (dp[pos] >= mod) dp[pos] -= mod;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;

        int[] x = new int[15], y = new int[15];
        int[] px = new int[1 << 5], py = new int[1 << 5], nx = new int[1 << 5], ny = new int[1 << 5];

        for (int i = 1; i <= n; i++) {
            in.nextToken();
            x[i] = (int) in.nval;
            in.nextToken();
            y[i] = (int) in.nval;
        }

        for (int i = 0; i <= (1 << n) - 1; i++) {
            for (int j = 1; j <= n; j++) {
                if (((i >> (j - 1)) & 1) != 0) {
                    if (x[j] > 0) px[i] += Math.abs(x[j]);
                    else nx[i] += Math.abs(x[j]);
                    if (y[j] > 0) py[i] += Math.abs(y[j]);
                    else ny[i] += Math.abs(y[j]);
                }
            }
        }

        dp = new int[31 * 21 * 21 * 21 * 21 * 2 * 2];
        dp[idx(0, 0, 0, 0, 0, 0, 0)] = 1;

        for (int i = 0; i <= 29; i++) {
            for (int cpx = 0; cpx <= 19; cpx++)
                for (int cnx = 0; cnx <= 19; cnx++)
                    for (int cpy = 0; cpy <= 19; cpy++)
                        for (int cny = 0; cny <= 19; cny++) {
                            for (int bx = 0; bx <= 1; bx++)
                                for (int by = 0; by <= 1; by++) {
                                    int cur = dp[idx(i, cpx, cnx, cpy, cny, bx, by)];
                                    if (cur != 0) {
                                        for (int msk = 0; msk <= (1 << n) - 1; msk++) {
                                            int npx = cpx + px[msk];
                                            int npy = cpy + py[msk];
                                            int nnx = cnx + nx[msk];
                                            int nny = cny + ny[msk];
                                            if ((npx & 1) != (nnx & 1)) continue;
                                            if ((npy & 1) != (nny & 1)) continue;
                                            int cx = (npx & 1), cy = (npy & 1);
                                            int mx = ((m >> i) & 1), my = mx;
                                            int nbx = (cx == mx) ? bx : ((cx > mx) ? 1 : 0);
                                            int nby = (cy == my) ? by : ((cy > my) ? 1 : 0);
                                            add(idx(i + 1, npx >> 1, nnx >> 1, npy >> 1, nny >> 1, nbx, nby), cur);
                                        }
                                    }
                                }
                        }
        }

        System.out.print((dp[idx(30, 0, 0, 0, 0, 0, 0)] + mod - 1) % mod);
    }
}
